// The dashboards' data (Phase 12): snapshot.json, generated by scripts/export_dashboard_snapshot.py from
// dashboard/data/tableau/*.csv (the Phase 9 batch, PII-free, synthetic). Each table is stored compactly (column names
// once, then one array of values per row); this module turns it into typed records and checks every column and
// value type, so a changed export fails loudly here (and in the Vitest tests) instead of drawing wrong charts.
import raw from './snapshot.json'

/** How a column is stored: s = text, n = number, ? = may be empty (null). */
type Kind = 's' | 's?' | 'n' | 'n?'
type Schema = Record<string, Kind>
type RowOf<S extends Schema> = {
  [K in keyof S]: S[K] extends 's' ? string : S[K] extends 's?' ? string | null : S[K] extends 'n' ? number : number | null
}

// (0/1) columns: 1 = yes, 0 = no, null = does not apply (so their average is a rate among the cases it applies to)
const OPERATIONS = {
  case: 's', docType: 's', systemOutcome: 's', outcome: 's', riskLevel: 's', applications: 'n',
  autoApproved: 'n', manualReview: 'n', resubmitRequired: 'n', timeToDecisionS: 'n?',
  docCheckS: 'n?', faceCheckS: 'n?', forgeryCheckS: 'n?', extractionCheckS: 'n?',
  funnel1: 'n', funnel2: 'n', funnel3: 'n', funnel4: 'n', funnel5: 'n', waitingForOfficer: 'n', queueAgeMin: 'n?',
} as const satisfies Schema

// One row per decision reason: a case's own numbers (applications, riskScore, the (0/1) columns) are on its FIRST
// row only (null on the others), so that adding them up counts every case once. See transforms.ts: caseRows().
const RISK_FRAUD = {
  case: 's', docType: 's', systemOutcome: 's', outcome: 's', riskLevel: 's', riskScoreBand: 'n', truthClass: 's',
  systemVsTruth: 's', reason: 's', reasonEffect: 's?', raisedBy: 's?', casesWithReason: 'n?', applications: 'n?',
  riskScore: 'n?', fraudCaught: 'n?', missedFraud: 'n?', falseAlarm: 'n?', officerConfirmedFlag: 'n?',
  officerAgreesWithTruth: 'n?',
} as const satisfies Schema

const MODEL_PERFORMANCE = {
  model: 's', version: 's', versionOrder: 'n', split: 's', metric: 's', value: 'n', chart: 's', field: 's?',
  matchType: 's?', note: 's?', source: 's',
} as const satisfies Schema

export type OperationsRow = RowOf<typeof OPERATIONS>
export type RiskFraudRow = RowOf<typeof RISK_FRAUD>
export type ModelRow = RowOf<typeof MODEL_PERFORMANCE>

export interface Snapshot {
  dataAsOf: string // ISO 8601, UTC: the latest recorded event of the batch (waiting times are measured at it)
  synthetic: boolean
  funnelStages: string[] // the names of funnel1 ... funnel5
  noReason: string // the reason label of a case's row when it has no reason
  operations: OperationsRow[]
  riskFraud: RiskFraudRow[]
  modelPerformance: ModelRow[]
}

type Cell = string | number | null
interface RawTable { columns: string[]; rows: Cell[][] }

function fits(value: Cell, kind: Kind): boolean {
  if (value === null) return kind.endsWith('?')
  return kind.startsWith('s') ? typeof value === 'string' : typeof value === 'number' && Number.isFinite(value)
}

function records<S extends Schema>(name: string, table: RawTable, schema: S): RowOf<S>[] {
  const keys = Object.keys(schema)
  if (table.columns.join() !== keys.join()) {
    throw new Error(`dashboard snapshot, ${name}: columns ${table.columns.join()} (expected ${keys.join()})`)
  }
  return table.rows.map((row, i) => {
    if (row.length !== keys.length) throw new Error(`dashboard snapshot, ${name} row ${i}: ${row.length} values`)
    const record: Record<string, Cell> = {}
    keys.forEach((key, j) => {
      if (!fits(row[j], schema[key])) throw new Error(`dashboard snapshot, ${name} row ${i}: bad ${key} ${row[j]}`)
      record[key] = row[j]
    })
    return record as RowOf<S>
  })
}

/** Parses and checks a snapshot (the bundled one by default; tests pass their own). */
export function parseSnapshot(data: unknown): Snapshot {
  const s = data as { schemaVersion: number; dataAsOf: string; synthetic: boolean; funnelStages: string[];
    noReason: string; tables: Record<'operations' | 'riskFraud' | 'modelPerformance', RawTable> }
  if (s.schemaVersion !== 1) throw new Error(`dashboard snapshot: schema version ${s.schemaVersion} (expected 1)`)
  if (Number.isNaN(Date.parse(s.dataAsOf))) throw new Error(`dashboard snapshot: bad dataAsOf ${s.dataAsOf}`)
  return {
    dataAsOf: s.dataAsOf,
    synthetic: s.synthetic,
    funnelStages: s.funnelStages,
    noReason: s.noReason,
    operations: records('operations', s.tables.operations, OPERATIONS),
    riskFraud: records('riskFraud', s.tables.riskFraud, RISK_FRAUD),
    modelPerformance: records('modelPerformance', s.tables.modelPerformance, MODEL_PERFORMANCE),
  }
}

export const snapshot: Snapshot = parseSnapshot(raw)
